# Put a hold on a person, from a date (blank: the sheet's today) to an optional to-date. Validate
# first so a bad date is a 400, not a 404. An unknown person is a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
# Last before the response: the hold is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonHold
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> body)
            throws InvalidPersonException {
        LocalDate from = date(request == null ? null : request.from(), "A hold's from-date is a date");
        LocalDate to = date(request == null ? null : request.to(), "A hold's to-date is a date");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidPersonException("A hold's to-date is not before its from-date");
        }
        body.set(new HoldInput(from, to));
    }

    private static LocalDate date(String value, String message) throws InvalidPersonException {
        String raw = value == null ? "" : value.trim();
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException(message);
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Adds a hold on the person, from the date given (the sheet's today when none is) until the
 * to-date given (none: open-ended). A to-date before the from-date is refused.
 */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Sheet sheet, @Val Person person,
            PersonRepository repository) throws InvalidPersonException {
        LocalDate from = input.from() != null ? input.from() : sheet.today();
        if (input.to() != null && input.to().isBefore(from)) {
            throw new InvalidPersonException("A hold's to-date is not before its from-date");
        }
        Hold hold = new Hold(from, input.to());
        person.getHolds().add(hold);
        repository.addHold(person, hold);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A hold on a person: from a date until an optional to-date (null: open-ended), both inclusive. */
public record Hold(LocalDate from, LocalDate to) {

    /** Whether the date is within the hold. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(from) && (to == null || !date.isAfter(to));
    }
}
