139	/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
140	public class Person {
141	    private Long id;
142	    private final String sheetId;
143	    private String name;
144	    private String grade;
145	    private Integer terms;
146	    private String contact;
147	    private long version;
148	    private int statementCount;
149	    private String statedTotal;
150	    private LocalDate statementDate;
151	    private LocalDate retiredFrom;
152	    private LocalDate addedOn;
153	    private final List<Hold> holds = new ArrayList<>();
154	    private final List<Long> patronIds = new ArrayList<>();
155	    private final List<String> aliases = new ArrayList<>();
156	    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();
157	
158	    public Person(Long id, String sheetId, String name, String grade) {
159	        this(id, sheetId, name, grade, 0);
160	    }
161	
162	    public Person(Long id, String sheetId, String name, String grade, long version) {
163	        this.id = id;
164	        this.sheetId = sheetId;
165	        this.name = name;
166	        this.grade = grade;
167	        this.version = version;
168	    }
169	
170	    public Long getId() { return id; }
171	    public void setId(Long id) { this.id = id; }
172	    public String getSheetId() { return sheetId; }
173	    public String getName() { return name; }
174	    public void setName(String name) { this.name = name; }
175	    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
176	    public String getGrade() { return grade; }
177	    public void setGrade(String grade) { this.grade = grade; }
178	    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
179	    public Integer getTerms() { return terms; }
180	    public void setTerms(Integer terms) { this.terms = terms; }
181	    /** Their contact, trimmed and lower-cased; null when they have none. */
182	    public String getContact() { return contact; }
183	    public void setContact(String contact) { this.contact = contact; }
184	    /** The grades recorded from a date, by from-date: each in force from it until the next. */
185	    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
186	    /** Record the grade from this date, replacing any recorded from the same date. */
187	    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
188	    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
189	    public String gradeOn(LocalDate date) {
190	        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
191	        return dated == null ? grade : dated.getValue();
192	    }
193	    /** Raised by one on each save; an edit names the version it was made from. */
194	    public long getVersion() { return version; }
195	    public void setVersion(long version) { this.version = version; }
196	    /** How many statements have been taken for them. */
197	    public int getStatementCount() { return statementCount; }
198	    /** The last statement's due-total (n/a when it had none); null before the first. */
199	    public String getStatedTotal() { return statedTotal; }
200	    /** The sheet's today when the last statement was taken; null before the first. */
201	    public LocalDate getStatementDate() { return statementDate; }
202	    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
203	        this.statementCount = count;
204	        this.statedTotal = statedTotal;
205	        this.statementDate = statementDate;
206	    }
207	    /** The sheet's today when they were added; null when it was not kept (from the beginning of time). */
208	    public LocalDate getAddedOn() { return addedOn; }
209	    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
210	    /** Whether they had been added by the end of {@code day}. */
211	    public boolean addedBy(LocalDate day) { return addedOn == null || !addedOn.isAfter(day); }
212	    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
213	    public LocalDate getRetiredFrom() { return retiredFrom; }
214	    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
215	    public boolean isRetired() { return retiredFrom != null; }
216	    /** Their holds, in the order added: each from a date to an optional to-date. */
217	    public List<Hold> getHolds() { return holds; }
218	    /** Whether they have any hold at all. */
219	    public boolean isHeld() { return !holds.isEmpty(); }
220	    /** Whether the date is within one of their holds: an OPEN claim on it, not bound by a statement, counts in no total. */
221	    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch((h) -> h.covers(date)); }
222	    /** Whether their retirement date is reached on {@code today}: retired from it or an earlier date. */
223	    public boolean retiredOn(LocalDate today) { return retiredFrom != null && today != null && !today.isBefore(retiredFrom); }
224	    /**
225	     * Whether an OPEN or PENDING claim of theirs on the date, not bound by a statement, counts in no
226	     * total on {@code today}: the date is within one of their holds, or their retirement date is reached.
227	     */
228	    public boolean heldOn(LocalDate date, LocalDate today) { return heldOn(date) || retiredOn(today); }
229	    /** The ids of the people they name as patrons, in the order named. */
230	    public List<Long> getPatronIds() { return patronIds; }
231	    /** Their aliases, trimmed, in the order given: like names, none equal (ignoring case) any name or alias on the sheet. */
232	    public List<String> getAliases() { return aliases; }
233	    /** Whether a claim on this date is refused: they are retired from an earlier date. */
234	    public boolean retiredBefore(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
235	}
