238	import java.sql.Date;
239	import java.sql.PreparedStatement;
240	import java.sql.Statement;
241	import java.time.LocalDate;
242	import java.util.HashMap;
243	import java.util.List;
244	import java.util.Map;
245	import java.util.Objects;
246	import org.springframework.jdbc.core.JdbcTemplate;
247	import org.springframework.jdbc.core.RowMapper;
248	import org.springframework.jdbc.support.GeneratedKeyHolder;
249	import org.springframework.stereotype.Repository;
250	
251	/** The people store, kept per sheet. */
252	@Repository
253	public class PersonRepository {
254	
255	    private static final String COLUMNS = "id, sheet_id, name, grade, terms, contact, version, statement_count, stated_total, statement_date, retired_from, added_on";
256	
257	    private static final RowMapper<Person> ROW = (rs, n) -> {
258	        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
259	                rs.getString("grade"), rs.getLong("version"));
260	        person.setTerms(rs.getObject("terms", Integer.class));
261	        person.setContact(rs.getString("contact"));
262	        person.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
263	                rs.getObject("statement_date", LocalDate.class));
264	        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
265	        person.setAddedOn(rs.getObject("added_on", LocalDate.class));
266	        return person;
267	    };
268	
269	    private final JdbcTemplate jdbc;
270	
271	    public PersonRepository(JdbcTemplate jdbc) {
272	        this.jdbc = jdbc;
273	    }
274	
275	    /** The sheet's people, in the order they were added. */
276	    public List<Person> findAll(String sheetId) {
277	        return findAll(sheetId, null);
278	    }
279	
280	    /**
281	     * The sheet's people, in the order they were added, as the list stood at the end of {@code day}
282	     * (null: now): those merged into another later than it are still on it.
283	     */
284	    public List<Person> findAll(String sheetId, LocalDate day) {
285	        List<Person> people = day == null
286	                ? jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND merged_into IS NULL ORDER BY id",
287	                        ROW, sheetId)
288	                : jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND (merged_into IS NULL"
289	                        + " OR merged_on > ?) ORDER BY id", ROW, sheetId, Date.valueOf(day));
290	        Map<Long, Person> byId = new HashMap<>();
291	        people.forEach((p) -> byId.put(p.getId(), p));
292	        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?",
293	                (rs) -> {
294	                    Person person = byId.get(rs.getLong("person_id"));
295	                    if (person != null) person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
296	                }, sheetId);
297	        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY person_id, named_seq NULLS FIRST, patron_id",
298	                (rs) -> {
299	                    Person person = byId.get(rs.getLong("person_id"));
300	                    if (person != null) person.getPatronIds().add(rs.getLong("patron_id"));
301	                }, sheetId);
302	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id",
303	                (rs) -> {
304	                    Person person = byId.get(rs.getLong("person_id"));
305	                    if (person != null) person.getHolds().add(hold(rs));
306	                }, sheetId);
307	        jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ? ORDER BY id",
308	                (rs) -> {
309	                    Person person = byId.get(rs.getLong("person_id"));
310	                    if (person != null) person.getAliases().add(rs.getString("alias"));
311	                }, sheetId);
312	        return people;
313	    }
314	
315	    /** The person with this id on the sheet, or null when there is none. */
316	    public Person find(String sheetId, long id) {
317	        List<Person> found = jdbc.query(
318	                "SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ? AND merged_into IS NULL",
319	                ROW, sheetId, id);
320	        if (found.isEmpty()) return null;
321	        Person person = found.get(0);
322	        loadGrades(person);
323	        loadHolds(person);
324	        person.getPatronIds().addAll(jdbc.queryForList(
325	                "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY named_seq NULLS FIRST, patron_id",
326	                Long.class, sheetId, id));
327	        loadAliases(person);
328	        return person;
329	    }
330	
331	    /** Record {@code alias} as one more of the person's aliases. */
332	    public void addAlias(Person person, String alias) {
333	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_on)"
334	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
335	                person.getSheetId(), person.getId(), alias, person.getSheetId());
336	        person.getAliases().add(alias);
337	    }
338	
339	    private void loadAliases(Person person) {
340	        person.getAliases().addAll(jdbc.queryForList(
341	                "SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id",
342	                String.class, person.getSheetId(), person.getId()));
343	    }
344	
345	    /**
346	     * Merge {@code from} into {@code into}: {@code from}'s name and aliases become {@code into}'s aliases;
347	     * their patrons are added to {@code into}'s (not {@code into} themselves, no repeats); anyone naming
348	     * {@code from} as patron names {@code into} instead (no repeats). {@code from}'s holds, watchers and
349	     * contact are dropped, and they are marked merged, leaving the list.
350	     */
351	    public void merge(Person from, Person into) {
352	        String sheetId = from.getSheetId();
353	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
354	        addAlias(into, from.getName());
355	        for (String alias : from.getAliases()) addAlias(into, alias);
356	        // Their own patrons go to the other, not the other themselves, nor one the other already names.
357	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ? AND (patron_id = ?"
358	                + " OR patron_id IN (SELECT p.patron_id FROM person_patron p WHERE p.person_id = ?))",
359	                sheetId, from.getId(), into.getId(), into.getId());
360	        jdbc.update("UPDATE person_patron SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
361	                into.getId(), sheetId, from.getId());
362	        // Those naming them name the other instead: not the other themselves, nor anyone already naming the other.
363	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ?"
364	                + " OR person_id IN (SELECT p.person_id FROM person_patron p WHERE p.patron_id = ?))",
365	                sheetId, from.getId(), into.getId(), into.getId());
366	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
367	                into.getId(), sheetId, from.getId());
368	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
369	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
370	        jdbc.update("UPDATE person SET contact = NULL, merged_into = ?, merged_on = (SELECT today FROM sheet WHERE id = ?),"
371	                + " version = version + 1 WHERE id = ? AND sheet_id = ?", into.getId(), sheetId, from.getId(), sheetId);
372	        jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND sheet_id = ?", into.getId(), sheetId);
373	    }
374	
375	    /**
376	     * Move the person to another sheet, with their grades (and from-dates), terms, contact and aliases,
377	     * as added there on that sheet's today: their statements start again at none and they are not
378	     * retired. Patron links either way, pool memberships, watches and holds are dropped. Their claims
379	     * are moved by the caller.
380	     */
381	    public void transfer(Person person, String toSheet) {
382	        long id = person.getId();
383	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", id, id);
384	        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", id);
385	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", id);
386	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", id);
387	        jdbc.update("DELETE FROM person_statement WHERE person_id = ?", id);
388	        jdbc.update("DELETE FROM person_statement_history WHERE person_id = ?", id);
389	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", id);
390	        jdbc.update("DELETE FROM person_grade_history WHERE person_id = ?", id);
391	        jdbc.update("DELETE FROM person_terms_history WHERE person_id = ?", id);
392	        jdbc.update("UPDATE person_grade SET sheet_id = ? WHERE person_id = ?", toSheet, id);
393	        jdbc.update("UPDATE person_alias SET sheet_id = ?, added_on = (SELECT today FROM sheet WHERE id = ?)"
394	                + " WHERE person_id = ?", toSheet, toSheet, id);
395	        jdbc.update("UPDATE person SET sheet_id = ?, statement_count = 0, stated_total = NULL, statement_date = NULL,"
396	                + " retired_from = NULL, added_on = (SELECT today FROM sheet WHERE id = ?), version = version + 1"
397	                + " WHERE id = ?", toSheet, toSheet, id);
398	        Person moved = find(toSheet, id);
399	        gradeHistory(moved, null, moved.getGrade());
400	        termsHistory(moved);
401	        moved.getDatedGrades().forEach((from, grade) -> gradeHistory(moved, from, grade));
402	    }
403	
404	    /** Record {@code patron} as one of the person's patrons. */
405	    public void addPatron(Person person, Person patron) {
406	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_on, named_seq)"
407	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?), NEXT VALUE FOR person_patron_seq)",
408	                person.getSheetId(), person.getId(), patron.getId(), person.getSheetId());
409	        person.getPatronIds().add(patron.getId());
410	    }
411	
412	    /**
413	     * The person on the sheet with this name or alias, ignoring case and surrounding spaces, or null
414	     * when there is none.
415	     */
416	    public Person findByName(String sheetId, String name) {
417	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND merged_into IS NULL"
418	                + " AND (LOWER(TRIM(name)) = LOWER(TRIM(?)) OR id IN (SELECT person_id FROM person_alias"
419	                + " WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?)))) ORDER BY id",
420	                ROW, sheetId, name, sheetId, name);
421	        if (found.isEmpty()) return null;
422	        loadGrades(found.get(0));
423	        loadHolds(found.get(0));
424	        loadAliases(found.get(0));
425	        return found.get(0);
426	    }
