428	    private void loadGrades(Person person) {
429	        jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
430	                (rs) -> {
431	                    person.setGradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class));
432	                }, person.getSheetId(), person.getId());
433	    }
434	
435	    private void loadHolds(Person person) {
436	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ? ORDER BY id",
437	                (rs) -> {
438	                    person.getHolds().add(hold(rs));
439	                }, person.getSheetId(), person.getId());
