446	    /** Record the person's dated grades as they hold them now, replacing those stored. */
447	    private void saveGrades(Person person) {
448	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?",
449	                person.getSheetId(), person.getId());
450	        person.getDatedGrades().forEach((from, grade) -> jdbc.update(
451	                "INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
452	                person.getSheetId(), person.getId(), Date.valueOf(from), grade));
453	    }
