459	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
460	        Integer count = jdbc.queryForObject(
461	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
462	                        + " AND id <> ? AND merged_into IS NULL",
463	                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
464	        Integer aliases = jdbc.queryForObject(
465	                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))",
466	                Integer.class, sheetId, name);
467	        return (count != null && count > 0) || (aliases != null && aliases > 0);
