470	    /**
471	     * Whether a person on any of the sheets, other than {@code exceptId}, has this as their name or
472	     * one of their aliases, ignoring case and surrounding spaces.
473	     */
474	    public boolean nameTakenIn(java.util.Collection<String> sheetIds, String name, Long exceptId) {
475	        for (String sheetId : sheetIds) {
476	            Integer count = jdbc.queryForObject(
477	                    "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
478	                            + " AND id <> ? AND merged_into IS NULL",
479	                    Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
480	            Integer aliases = jdbc.queryForObject(
481	                    "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))"
482	                            + " AND person_id <> ?",
483	                    Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
484	            if ((count != null && count > 0) || (aliases != null && aliases > 0)) return true;
485	        }
