489	    /** Every name and alias of the people on the sheets, trimmed and lower-cased. */
490	    public java.util.Set<String> namesIn(java.util.Collection<String> sheetIds) {
491	        java.util.Set<String> names = new java.util.HashSet<>();
492	        for (String sheetId : sheetIds) {
493	            jdbc.queryForList("SELECT name FROM person WHERE sheet_id = ? AND merged_into IS NULL", String.class, sheetId)
494	                    .forEach((n) -> names.add(asName(n)));
495	            jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ?", String.class, sheetId)
496	                    .forEach((a) -> names.add(asName(a)));
497	        }
