501	    /** Whether the person's name or any of their aliases is in {@code names} (trimmed and lower-cased). */
502	    public static boolean clashes(Person person, java.util.Set<String> names) {
503	        if (names.contains(asName(person.getName()))) return true;
504	        return person.getAliases().stream().anyMatch((a) -> names.contains(asName(a)));
