512	    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
513	        Integer count = jdbc.queryForObject(
514	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
515	                Integer.class, sheetId, contact, exceptId == null ? -1L : exceptId);
516	        return count != null && count > 0;
