519	    /**
520	     * Record the person's statements (their count, last due-total and date), leaving the rest as stored.
521	     * The last statement is kept as the one numbered by the count; any numbered after it are dropped.
522	     */
523	    public void saveStatements(Person person) {
524	        Date date = person.getStatementDate() == null ? null : Date.valueOf(person.getStatementDate());
525	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE id = ? AND sheet_id = ?",
526	                person.getStatementCount(), person.getStatedTotal(), date,
527	                person.getId(), person.getSheetId());
528	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq >= ?",
529	                person.getSheetId(), person.getId(), person.getStatementCount());
530	        if (person.getStatementCount() > 0) {
531	            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date) VALUES (?, ?, ?, ?, ?)",
532	                    person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(), date);
533	        }
534	        jdbc.update("INSERT INTO person_statement_history (sheet_id, person_id, statement_count, stated_total, statement_date, set_on)"
535	                + " VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
536	                person.getSheetId(), person.getId(), person.getStatementCount(), person.getStatedTotal(), date,
537	                person.getSheetId());
538	    }
539	
540	    /**
541	     * The person's statement numbered {@code seq} (from 1): its due-total and date, or null when it
542	     * was not kept (taken before statements were kept), or there is none.
543	     */
544	    public StatedFigure findStatement(Person person, int seq) {
545	        List<StatedFigure> found = jdbc.query(
546	                "SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND seq = ?",
547	                (rs, n) -> new StatedFigure(rs.getString("stated_total"), rs.getObject("statement_date", LocalDate.class)),
548	                person.getSheetId(), person.getId(), seq);
549	        return found.isEmpty() ? null : found.get(0);
550	    }
551	
552	    /** Record the date the person is retired from, leaving the rest as stored. */
553	    public void saveRetired(Person person) {
554	        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?",
555	                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()),
556	                person.getId(), person.getSheetId());
557	        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, set_on)"
558	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
559	                person.getSheetId(), person.getId(),
560	                person.getRetiredFrom() == null ? null : Date.valueOf(person.getRetiredFrom()), person.getSheetId());
561	    }
562	
563	    /** Record a new hold on the person, leaving the rest as stored. */
564	    public void addHold(Person person, Hold hold) {
565	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, made_on)"
566	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
567	                person.getSheetId(), person.getId(), Date.valueOf(hold.from()),
568	                hold.to() == null ? null : Date.valueOf(hold.to()), person.getSheetId());
569	    }
570	
571	    /**
572	     * Insert a new person (assigning its id) or update an existing one, raising its version. False
573	     * when the stored person is no longer at the version it was loaded at: nothing is written.
574	     */
575	    public boolean save(Person person) {
576	        if (person.getId() != null) {
577	            List<String> storedGrade = jdbc.queryForList("SELECT grade FROM person WHERE id = ? AND sheet_id = ?",
578	                    String.class, person.getId(), person.getSheetId());
579	            List<Integer> storedTerms = jdbc.query("SELECT terms FROM person WHERE id = ? AND sheet_id = ?",
580	                    (rs, n) -> rs.getObject("terms", Integer.class), person.getId(), person.getSheetId());
581	            Map<LocalDate, String> storedDated = new HashMap<>();
582	            jdbc.query("SELECT from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
583	                    (rs) -> {
584	                        storedDated.put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
585	                    }, person.getSheetId(), person.getId());
586	            int updated = jdbc.update("UPDATE person SET name = ?, grade = ?, terms = ?, contact = ?, version = version + 1"
587	                    + " WHERE id = ? AND sheet_id = ? AND version = ?",
588	                    person.getName(), person.getGrade(), person.getTerms(), person.getContact(), person.getId(), person.getSheetId(),
589	                    person.getVersion());
590	            if (updated == 0) return false;
591	            person.setVersion(person.getVersion() + 1);
592	            saveGrades(person);
593	            if (storedGrade.isEmpty() || !storedGrade.get(0).equals(person.getGrade())) {
594	                gradeHistory(person, null, person.getGrade());
595	            }
596	            if (storedTerms.isEmpty() || !Objects.equals(storedTerms.get(0), person.getTerms())) termsHistory(person);
597	            person.getDatedGrades().forEach((from, grade) -> {
598	                if (!grade.equals(storedDated.get(from))) gradeHistory(person, from, grade);
599	            });
600	            return true;
601	        }
602	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
603	        jdbc.update(con -> {
604	            PreparedStatement ps = con.prepareStatement(
605	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on) VALUES (?, ?, ?, ?, ?,"
606	                            + " (SELECT today FROM sheet WHERE id = ?))",
607	                    Statement.RETURN_GENERATED_KEYS);
608	            ps.setString(1, person.getSheetId());
609	            ps.setString(2, person.getName());
610	            ps.setString(3, person.getGrade());
611	            ps.setObject(4, person.getTerms(), java.sql.Types.INTEGER);
612	            ps.setString(5, person.getContact());
613	            ps.setString(6, person.getSheetId());
614	            return ps;
615	        }, keys);
616	        person.setId(keys.getKey().longValue());
617	        person.setAddedOn(jdbc.queryForObject("SELECT added_on FROM person WHERE id = ?", LocalDate.class, person.getId()));
618	        saveGrades(person);
619	        gradeHistory(person, null, person.getGrade());
620	        termsHistory(person);
621	        person.getDatedGrades().forEach((from, grade) -> gradeHistory(person, from, grade));
622	        return true;
623	    }
624	
625	    /** Keeps a grade given to the person (from {@code from}; null: their first grade) in its history, with the sheet's today now. */
626	    private void gradeHistory(Person person, LocalDate from, String grade) {
627	        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, from_date, grade, set_on)"
628	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
629	                person.getSheetId(), person.getId(), from == null ? null : Date.valueOf(from), grade, person.getSheetId());
630	    }
631	
632	    /** Keeps the person's terms (null: none) in their history, with the sheet's today now. */
633	    private void termsHistory(Person person) {
634	        jdbc.update("INSERT INTO person_terms_history (sheet_id, person_id, terms, set_on)"
635	                + " VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
636	                person.getSheetId(), person.getId(), person.getTerms(), person.getSheetId());
637	    }
638	
639	    /**
640	     * The person as they stood at the end of {@code day}: their grades, terms, holds, retirement, statements,
641	     * aliases and patrons as given while the sheet's today was on or before it; the rest as they are now.
642	     */
643	    public Person asOf(Person person, LocalDate day) {
644	        Date on = Date.valueOf(day);
645	        String[] first = { person.getGrade() };
646	        Map<LocalDate, String> dated = new HashMap<>();
647	        jdbc.query("SELECT from_date, grade FROM person_grade_history WHERE sheet_id = ? AND person_id = ?"
648	                + " AND set_on <= ? ORDER BY id", (rs) -> {
649	                    LocalDate from = rs.getObject("from_date", LocalDate.class);
650	                    if (from == null) first[0] = rs.getString("grade");
651	                    else dated.put(from, rs.getString("grade"));
652	                }, person.getSheetId(), person.getId(), on);
653	        Person then = new Person(person.getId(), person.getSheetId(), person.getName(), first[0], person.getVersion());
654	        List<Integer> terms = jdbc.query("SELECT terms FROM person_terms_history WHERE sheet_id = ? AND person_id = ?"
655	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("terms", Integer.class),
656	                person.getSheetId(), person.getId(), on);
657	        then.setTerms(terms.isEmpty() ? null : terms.get(0));
658	        then.setContact(person.getContact());
659	        then.getAliases().addAll(jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ?"
660	                + " AND (added_on IS NULL OR added_on <= ?) ORDER BY id", String.class, person.getSheetId(), person.getId(), on));
661	        then.setAddedOn(person.getAddedOn());
662	        then.setStatements(0, null, null);
663	        jdbc.query("SELECT statement_count, stated_total, statement_date FROM person_statement_history"
664	                + " WHERE sheet_id = ? AND person_id = ? AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs) -> {
665	                    then.setStatements(rs.getInt("statement_count"), rs.getString("stated_total"),
666	                            rs.getObject("statement_date", LocalDate.class));
667	                }, person.getSheetId(), person.getId(), on);
668	        dated.forEach((from, grade) -> then.setGradeFrom(grade, from));
669	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ?"
670	                + " AND (made_on IS NULL OR made_on <= ?) ORDER BY id", (rs) -> {
671	                    then.getHolds().add(hold(rs));
672	                }, person.getSheetId(), person.getId(), on);
673	        List<LocalDate> retired = jdbc.query("SELECT from_date FROM person_retirement WHERE sheet_id = ? AND person_id = ?"
674	                + " AND set_on <= ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("from_date", LocalDate.class),
675	                person.getSheetId(), person.getId(), on);
676	        then.setRetiredFrom(retired.isEmpty() ? null : retired.get(0));
677	        then.getPatronIds().addAll(jdbc.queryForList("SELECT patron_id FROM person_patron WHERE sheet_id = ?"
678	                + " AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY named_seq NULLS FIRST, patron_id", Long.class,
679	                person.getSheetId(), person.getId(), on));
680	        return then;
681	    }
682	}
