# Retire a person from a date (blank: the sheet's today). Validate first so a bad date is a 400,
# not a 404. From the day the retirement date is reached, their OPEN and PENDING claims not bound
# by a statement leave every total: retiring moves figures like any other change.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
# Last before the response: the retirement is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonRetired
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# The signed-in user starts (on) or stops (off) watching a person. Watching is the user's own: it
# moves no figures. Already so: nothing is written.
# A viewer may change nothing, a watch included: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.watch.ValidateWatch
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: watch
watch:
  class: net.officefloor.hq.app.watch.WatchPerson
  govern: [ transaction ]
  next: audit
# Last before the response: the watch is saved.
audit:
  class: net.officefloor.hq.app.watch.AuditPersonWatched
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.watch.RespondWithWatches
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("personId") String personId, @Val Sheet sheet,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Person person = null;
        try {
            person = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Sheet sheet, @Val Person person, PersonRepository people, SheetRepository sheets,
            ObjectResponse<PersonResponse> response) {
        boolean clashing = PersonRepository.clashes(person, people.namesIn(sheets.tree(sheet.id())));
        response.send(PersonResponse.from(person, sheet.today(), clashing));
    }
}
-- A pool member may be another pool on the sheet instead of a person: exactly one of person_id and
-- member_pool_id is set. A pool is a member of at most one pool.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool(id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_pool_once UNIQUE (member_pool_id);
-- The order a person's patrons were named in (null for those named before it was kept: before the
-- rest, by patron id). The first-named patron takes the remainder of the shares.
CREATE SEQUENCE person_patron_seq;
ALTER TABLE person_patron ADD COLUMN named_seq BIGINT;
