package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateMove {
    public void validate(@RequestBody MoveRequest request, Out<MoveInput> body) throws InvalidPersonException {
        String direction = request == null || request.direction() == null ? "" : request.direction().trim();
        switch (direction) {
            case "up" -> body.set(new MoveInput(true));
            case "down" -> body.set(new MoveInput(false));
            default -> throw new InvalidPersonException("A move is up or down");
        }
    }
}
EOF
cat > MovePerson.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Swaps the person with the one above or below them in the list. The top row cannot move up nor
 * the bottom row down: refused, writing nothing.
 */
public class MovePerson {
    public void move(@Val MoveInput input, @Val Person person, PersonRepository repository, Out<Moved> moved)
            throws InvalidPersonException {
        Integer position = repository.move(person, input.up());
        if (position == null) {
            throw new InvalidPersonException(input.up() ? "The top row cannot move up" : "The bottom row cannot move down");
        }
        moved.set(new Moved(position));
    }
}
EOF
cat > AuditPersonMoved.java <<'EOF'
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the move: the person's new position, counting from 1. Runs after it is saved. */
public class AuditPersonMoved {
    public void audit(@Val Sheet sheet, @Val Person person, @Val Moved moved,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_MOVED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " position=" + moved.position());
    }
}
EOF
cat > '../../../../../../resources/officefloor/rest/api/sheets/{sheetId}/people/{personId}/move.POST.yml' <<'EOF'
# Move a person up or down the list: swapped with the one above or below. Validate first so a bad
# direction is a 400, not a 404. An unknown person is a 404; the top row moving up, or the bottom
# row down, is a 400 and writes nothing. The list's order moves no figures.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateMove
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: move
move:
  class: net.officefloor.hq.app.person.MovePerson
  govern: [ transaction ]
  next: audit
# Last before the response: the move is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonMoved
  govern: [ transaction ]
